INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64561302', 64561302, 'analyze_legacy', 'Provinsi Jawa Timur', 'provinsi', 'DINAS KELAUTAN DAN PERIKANAN', 'Pengadaan Paket Bimtek NATURE - Youth Skills Development for Sustainable Aquaculture', 'Barang', 'E-Purchasing', 'Jawa Timur, Surabaya (Kota)', 269607000, 'April 2026', 'APBD', 1, 1, '1 paket', 'Pengadaan Paket Bimtek NATURE - Youth Skills Development for Sustainable Aquaculture', 'Benih Lele Uk minimal 5-7 cm; Keseragaman ukuran minimal 90%; Kondisi sehat, pergerakan lincah, tidak cacat dan respon terhadap pakan bagus; Dilampiri Surat Keterangan Asal (SKA). Kolam Terpal Bundar Diameter minimal ± 3 meter; Tinggi terpal karet ± 1,2 meter; Kontruksi kerangka besi wadah budidaya (ex. Wiremesh); Bahan besi wiremesh = besi Ø minimal 6 mm; Model = knock down (bongkar pasang); Ukuran kontruksi besi = diameter 300 cm tinggi 100 cm; Besi dicat; Ring bata tinggi 30 cm diplester dan diaci; Bagian ruang dalam ring bata diisi pasir dan tinggi ketebalan pasir 5 cm rata penuh; Pipa pengeluaran central drainase 2,5". Probiotik Probiotik Dan Enzym, Uk 500 Gram Serok Panen Pompa Air Gasoline Diameter buang / hisap : 3 Inch / 80 mm; Kedalaman hisap : 7 m; Tinggi hisap 8 m; Tinggi Dorong 30 m; Power speed : 3.600 rpm; Kapasitas bahan bakar 3,6 liter; Max. capacity (L/min) 60 m3/jam; Kelengkapan (shock, klem, sarangan, selang lipat Ø 3 inch : 1 Roll / 25 m dan selang spiral Ø 3 inch : 5 m). Pakan Pelet Apung (Lele) Jenis : apung; Nutrisi : protein minimal 30%; Tercantum : tanggal kadaluarsa; Terdaftar pada Kementrian Kelautan dan Perikanan Republik Indonesia; Jumlah komposisi ukuran pakan menyesuaikan dengan kebutuhan (starter -1, growth -2 dan -3); Pakan Ikan Lele 8505 Tongwei Feed atau HI-PRO-VITE 781 atau MS Prima Feed LP Premium Grade.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1609009);
